}

/** @internal */
export function assertWindowName(name: unknown, method: string): asserts name is string {
	if (typeof name !== 'string' || name.length === 0) {
		throw new Error(`${method}: window name must be a non-empty string`);
	}
	if (name.trim().length === 0) {
		throw new Error(`${method}: window name must not be whitespace-only`);
	}
}

/** Builds the contents of a window specification (without surrounding parentheses). */
export function buildWindowSpec(spec: WindowSpec | undefined): SQL {
	const chunks: SQL[] = [];
	const partitionBy = toArray(spec?.partitionBy);
	if (partitionBy.length > 0) {
		chunks.push(sql`partition by ${sql.join(partitionBy, sql`, `)}`);
	}
	const orderBy = toArray(spec?.orderBy);
	if (orderBy.length > 0) {
		chunks.push(sql`order by ${sql.join(orderBy, sql`, `)}`);
	}
	if (spec?.frame) {
		if (!is(spec.frame, WindowFrame)) {
			throw new Error('Window frame must be created with rows() or range()');
		}
		chunks.push(spec.frame.getSQL());
	}
	return sql.join(chunks, sql` `);
}

/** A named window definition, rendered as `"name" as (<spec>)` in a `window` clause. */
export interface WindowDefinition {
	name: string;
	spec: WindowSpec;
}

/** @internal */
export function buildWindowClause(windows: WindowDefinition[] | undefined): SQL | undefined {
	if (!windows || windows.length === 0) return undefined;
	return sql` window ${
		sql.join(
			windows.map(({ name, spec }) => sql`${sql.identifier(name)} as (${buildWindowSpec(spec)})`),
			sql`, `,
		)
	}`;
}

// ---------------------------------------------------------------------------
// Window functions
// ---------------------------------------------------------------------------

export class WindowFunction<T = unknown> {
	static readonly [entityKind]: string = 'WindowFunction';

	declare readonly _: { readonly type: T };

	constructor(
		private readonly fn: SQL,
		private readonly decoder?: Parameters<SQL['mapWith']>[0],
	) {}

	/**
	 * Adds an `over` clause, turning the function call into a window expression.
	 *
	 * @param window an inline window specification, or the name of a window
	 * defined with `.window(name, spec)` on the select query.
	 */
	over(window?: WindowSpec | string): SQL<T> {
		let result: SQL;
		if (typeof window === 'string') {
			assertWindowName(window, 'over()');
			result = sql`${this.fn} over ${sql.identifier(window)}`;
		} else {
			result = sql`${this.fn} over (${buildWindowSpec(window)})`;
		}
		return (this.decoder ? result.mapWith(this.decoder) : result) as SQL<T>;
	}
}

function assertPositiveInteger(fnName: string, value: unknown): asserts value is number {
	if (typeof value !== 'number' || !Number.isInteger(value) || value <= 0) {
		throw new Error(`${fnName}() expects a positive integer, received: ${String(value)}`);
	}
}

function assertNonNegativeInteger(fnName: string, value: unknown): asserts value is number {
	if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
		throw new Error(`${fnName}() expects a non-negative integer offset, received: ${String(value)}`);
	}
}

function decoderFor(expression: SQLWrapper) {
	if (is(expression, Column)) return expression;
	if (is(expression, SQL)) return (expression as any).decoder;
	if (is(expression, SQL.Aliased)) return (expression.sql as any).decoder;
	return undefined;
}

function valueChunk(value: unknown, expression: SQLWrapper): SQLWrapper {
	if (typeof value === 'number' || typeof value === 'bigint') {
		// numeric literals are inlined to avoid untyped parameters in polymorphic functions
		return sql.raw(String(value));
	}
	if (isSQLWrapper(value)) return value;
	return is(expression, Column) ? sql.param(value, expression) : sql.param(value);
}

/** `row_number()` - number of the current row within its partition, counting from 1. */
export function rowNumber(): WindowFunction<number> {
	return new WindowFunction(sql`row_number()`, Number);
}

/** `rank()` - rank of the current row with gaps. */
export function rank(): WindowFunction<number> {
	return new WindowFunction(sql`rank()`, Number);
}

/** `dense_rank()` - rank of the current row without gaps. */
export function denseRank(): WindowFunction<number> {
	return new WindowFunction(sql`dense_rank()`, Number);
}

/** `ntile(n)` - integer ranging from 1 to `buckets`, dividing the partition as equally as possible. */
export function ntile(buckets: number): WindowFunction<number> {
	assertPositiveInteger('ntile', buckets);
	return new WindowFunction(sql`ntile(${sql.raw(String(buckets))})`, Number);
}

/** `percent_rank()` - relative rank of the current row: (rank - 1) / (total partition rows - 1). */
export function percentRank(): WindowFunction<number> {
	return new WindowFunction(sql`percent_rank()`, Number);
}

/** `cume_dist()` - cumulative distribution of the current row. */
export function cumeDist(): WindowFunction<number> {
	return new WindowFunction(sql`cume_dist()`, Number);
}

function offsetFunction(
	name: 'lag' | 'lead',
	expression: SQLWrapper,
	offset: number | undefined,
	defaultValue: unknown,
): WindowFunction<any> {
	const args: SQLWrapper[] = [expression];
	if (offset !== undefined || defaultValue !== undefined) {
		const resolvedOffset = offset ?? 1;
		assertNonNegativeInteger(name, resolvedOffset);
		args.push(sql.raw(String(resolvedOffset)));
	}
	if (defaultValue !== undefined) {
		args.push(valueChunk(defaultValue, expression));
	}
	return new WindowFunction(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`, decoderFor(expression));
}

/**
 * `lag(expression[, offset[, default]])` - value of `expression` at the row `offset` rows before the current row.
 * The result is nullable unless a `default` value is provided.
 */
export function lag<T extends SQLWrapper>(
	expression: T,
	offset?: number,
): WindowFunction<InferExpressionType<T> | null>;
export function lag<T extends SQLWrapper>(
	expression: T,
	offset: number | undefined,
	defaultValue: InferExpressionType<T> | SQLWrapper,
): WindowFunction<NonNullable<InferExpressionType<T>>>;
export function lag(expression: SQLWrapper, offset?: number, defaultValue?: unknown): WindowFunction<any> {
	return offsetFunction('lag', expression, offset, defaultValue);
}

/**
 * `lead(expression[, offset[, default]])` - value of `expression` at the row `offset` rows after the current row.
 * The result is nullable unless a `default` value is provided.
 */
export function lead<T extends SQLWrapper>(
	expression: T,
	offset?: number,
): WindowFunction<InferExpressionType<T> | null>;
export function lead<T extends SQLWrapper>(
	expression: T,
	offset: number | undefined,
	defaultValue: InferExpressionType<T> | SQLWrapper,
): WindowFunction<NonNullable<InferExpressionType<T>>>;
export function lead(expression: SQLWrapper, offset?: number, defaultValue?: unknown): WindowFunction<any> {
	return offsetFunction('lead', expression, offset, defaultValue);
}

/** `first_value(expression)` - value of `expression` at the first row of the window frame. */
export function firstValue<T extends SQLWrapper>(expression: T): WindowFunction<InferExpressionType<T> | null> {
	return new WindowFunction(sql`first_value(${expression})`, decoderFor(expression));
}

/** `last_value(expression)` - value of `expression` at the last row of the window frame. */
export function lastValue<T extends SQLWrapper>(expression: T): WindowFunction<InferExpressionType<T> | null> {
	return new WindowFunction(sql`last_value(${expression})`, decoderFor(expression));
}

/** `nth_value(expression, n)` - value of `expression` at the `n`-th row of the window frame (counting from 1). */
export function nthValue<T extends SQLWrapper>(
	expression: T,
	n: number,
): WindowFunction<InferExpressionType<T> | null> {
	assertPositiveInteger('nthValue', n);
	return new WindowFunction(sql`nth_value(${expression}, ${sql.raw(String(n))})`, decoderFor(expression));
}

/** `sum(expression) over (...)` */
export function windowSum(expression: SQLWrapper): WindowFunction<string | null> {
	return new WindowFunction(sql`sum(${expression})`, String);
}

/** `avg(expression) over (...)` */
export function windowAvg(expression: SQLWrapper): WindowFunction<string | null> {
	return new WindowFunction(sql`avg(${expression})`, String);
}

/** `min(expression) over (...)` */
export function windowMin<T extends SQLWrapper>(
	expression: T,
): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | null> {
	return new WindowFunction(sql`min(${expression})`, is(expression, Column) ? expression : String);
}

/** `max(expression) over (...)` */
export function windowMax<T extends SQLWrapper>(
	expression: T,
): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | null> {
	return new WindowFunction(sql`max(${expression})`, is(expression, Column) ? expression : String);
}

/** `count(expression) over (...)`, or `count(*) over (...)` when called without an argument. */
export function windowCount(expression?: SQLWrapper): WindowFunction<number> {
	return new WindowFunction(sql`count(${expression ?? sql.raw('*')})`, Number);
}

