import { describe, expect, expectTypeOf, it } from 'vitest';
import {
	asc,
	cumeDist,
	currentRow,
	denseRank,
	desc,
	firstValue,
	following,
	lag,
	lastValue,
	lead,
	nthValue,
	ntile,
	percentRank,
	preceding,
	range,
	rank,
	rowNumber,
	rows,
	unboundedFollowing,
	unboundedPreceding,
	windowAvg,
	windowCount,
	windowMax,
	windowMin,
	windowSum,
} from '~/index';
import { MySqlDialect, int as mysqlInt, mysqlTable } from '~/mysql-core';
import { integer, PgDialect, pgTable, text } from '~/pg-core';
import { QueryBuilder as PgQueryBuilder } from '~/pg-core/query-builders/query-builder';
import { SingleStoreDialect } from '~/singlestore-core';
import { integer as sqliteInteger, SQLiteDialect, sqliteTable } from '~/sqlite-core';
import { QueryBuilder as MySqlQueryBuilder } from '~/mysql-core/query-builders/query-builder';
import { QueryBuilder as SQLiteQueryBuilder } from '~/sqlite-core/query-builders/query-builder';
import { QueryBuilder as GelQueryBuilder } from '~/gel-core/query-builders/query-builder';
import { QueryBuilder as SingleStoreQueryBuilder } from '~/singlestore-core/query-builders/query-builder';
import { GelDialect, gelTable, integer as gelInteger } from '~/gel-core';
import { int as ssInt, singlestoreTable } from '~/singlestore-core';
import type { SQL } from '~/sql/sql';

const employees = pgTable('employees', {
	id: integer('id').primaryKey(),
	name: text('name').notNull(),
	dept: text('dept'),
	salary: integer('salary').notNull(),
});

const dialect = new PgDialect();
const q = (s: SQL) => dialect.sqlToQuery(s);

describe('window functions', () => {
	it('ranking functions', () => {
		expect(q(rowNumber().over()).sql).toBe('row_number() over ()');
		expect(q(rank().over({})).sql).toBe('rank() over ()');
		expect(q(denseRank().over({ orderBy: desc(employees.salary) })).sql).toBe(
			'dense_rank() over (order by "employees"."salary" desc)',
		);
		expect(q(percentRank().over()).sql).toBe('percent_rank() over ()');
		expect(q(cumeDist().over()).sql).toBe('cume_dist() over ()');
		const n = q(ntile(4).over({ partitionBy: [employees.dept], orderBy: [asc(employees.salary)] }));
		expect(n.sql).toBe('ntile(4) over (partition by "employees"."dept" order by "employees"."salary" asc)');
		expect(n.params).toEqual([]);
	});

	it('positional arguments are inlined', () => {
		expect(q(lag(employees.salary).over()).sql).toBe('lag("employees"."salary") over ()');
		const l = q(lag(employees.salary, 0, 0).over());
		expect(l.sql).toBe('lag("employees"."salary", 0, 0) over ()');
		expect(l.params).toEqual([]);
		expect(q(lead(employees.salary, 2).over()).sql).toBe('lead("employees"."salary", 2) over ()');
		expect(q(firstValue(employees.name).over()).sql).toBe('first_value("employees"."name") over ()');
		expect(q(lastValue(employees.name).over()).sql).toBe('last_value("employees"."name") over ()');
		expect(q(nthValue(employees.name, 3).over('w')).sql).toBe('nth_value("employees"."name", 3) over "w"');
	});

	it('aggregates', () => {
		expect(q(windowCount().over()).sql).toBe('count(*) over ()');
		expect(q(windowCount(employees.id).over()).sql).toBe('count("employees"."id") over ()');
		expect(q(windowSum(employees.salary).over()).sql).toBe('sum("employees"."salary") over ()');
		expect(q(windowAvg(employees.salary).over()).sql).toBe('avg("employees"."salary") over ()');
		expect(q(windowMin(employees.salary).over()).sql).toBe('min("employees"."salary") over ()');
		expect(q(windowMax(employees.salary).over()).sql).toBe('max("employees"."salary") over ()');
	});

	it('frames', () => {
		expect(
			q(windowSum(employees.salary).over({
				orderBy: employees.id,
				frame: rows({ from: unboundedPreceding, to: currentRow }),
			})).sql,
		).toBe('sum("employees"."salary") over (order by "employees"."id" rows between unbounded preceding and current row)');
		const r = q(windowAvg(employees.salary).over({ frame: range({ from: preceding(0), to: following(2) }) }));
		expect(r.sql).toBe('avg("employees"."salary") over (range between 0 preceding and 2 following)');
		expect(r.params).toEqual([]);
		expect(q(rowNumber().over({ frame: rows({ from: currentRow, to: unboundedFollowing }) })).sql).toBe(
			'row_number() over (rows between current row and unbounded following)',
		);
	});

	it('validation', () => {
		expect(() => ntile(0)).toThrow(/ntile.*0/);
		expect(() => ntile(1.5)).toThrow(/ntile.*1\.5/);
		expect(() => nthValue(employees.name, -1)).toThrow(/nthValue.*-1/);
		expect(() => preceding(-1)).toThrow(/preceding/);
		expect(() => following(1.5)).toThrow(/following/);
		expect(() => rows({ from: currentRow, to: preceding(1) })).toThrow(/from/);
		expect(() => range({ from: following(3), to: following(1) })).toThrow(/from/);
		expect(() => new PgQueryBuilder().select().from(employees).window('', {})).toThrow(/non-empty/);
		expect(() => new PgQueryBuilder().select().from(employees).window('  ', {})).toThrow(/whitespace/);
	});

	it('named windows across dialects', () => {
		const pg = new PgQueryBuilder().select({ r: rank().over('w') }).from(employees)
			.window('w', { partitionBy: employees.dept, orderBy: desc(employees.salary) })
			.orderBy(employees.id);
		expect(pg.toSQL().sql).toBe(
			'select rank() over "w" from "employees" window "w" as (partition by "employees"."dept" order by "employees"."salary" desc) order by "employees"."id"',
		);

		const m = mysqlTable('t', { id: mysqlInt('id') });
		expect(new MySqlQueryBuilder().select({ r: rowNumber().over('w') }).from(m).window('w', { orderBy: m.id }).toSQL().sql)
			.toBe('select row_number() over `w` from `t` window `w` as (order by `t`.`id`)');
		const s = sqliteTable('t', { id: sqliteInteger('id') });
		expect(new SQLiteQueryBuilder().select({ r: rowNumber().over('w') }).from(s).window('w', {}).toSQL().sql)
			.toBe('select row_number() over "w" from "t" window "w" as ()');
		const g = gelTable('t', { id: gelInteger('id') });
